import json,re,decimal,collections,statistics,math,os

def external(out,gt):
 m=re.findall(r'####\s*(-?[0-9]+(?:\.[0-9]+)?(?:,[0-9]+)?)',out)
 if not m:return False,None
 s=m[-1].replace(',','')
 try:return float(s)==float(gt),s
 except:return s==gt,s
for fn in ['results/run100/val_generations/0.jsonl','results/run100/val_generations/50.jsonl','results/run100/val_generations/100.jsonl']:
 rows=[json.loads(x) for x in open(fn)]
 cnt=collections.Counter(); mism=[]; no=[]; internal=[]
 for i,x in enumerate(rows):
  ok,p=external(x['output'],x['gts']); cnt[('ok' if ok else 'bad', 'has' if p is not None else 'none')]+=1
  if p is None:no.append(i)
  if ok != (float(x.get('acc',0))>0.5): mism.append((i,ok,p,x['gts'],x.get('acc'),x['output'][-500:]))
  internal.append(float(x.get('acc',0)))
 print(fn, 'rows',len(rows),'external',sum(external(x['output'],x['gts'])[0] for x in rows)/len(rows),'internal',sum(internal)/len(rows),'cnt',cnt,'no',len(no),'mismatch',len(mism))
 print('out lengths',statistics.mean(map(lambda x:len(x['output']),rows)),statistics.median(map(lambda x:len(x['output']),rows)),statistics.quantiles(map(lambda x:len(x['output']),rows),n=10)[-1], 'trunc-looking',sum(len(x['output'])>=2000 for x in rows))
 for z in mism[:3]: print('MISM',z[:5],repr(z[5]))
 # print no examples
 for i in no[:2]:print('NO',i,repr(rows[i]['output'][-500:]))
PY",workdir:"/workspace",yield_time_ms:10000,max_output_tokens:30000}),
