 rows=[json.loads(x) for x in open(fn)]
 print('\n',fn,len(rows),rows[0].keys())
 for k in rows[0]:
  if isinstance(rows[0][k],(str,int,float,bool)): print(k,repr(rows[0][k])[:180])
 # inspect field values / score
 for k in ['reward','score','acc','response_length','output','gts','step']:
  if k in rows[0]:
   vals=[x[k] for x in rows]
   print(k,'types',collections.Counter(type(v).__name__ for v in vals),'sample',repr(vals[0])[:100])
 if 'reward' in rows[0]:
  print('reward counts',collections.Counter(str(x['reward']) for x in rows).most_common(10))
 if 'output' in rows[0]: print('len',statistics.mean(len(x['output']) for x in rows), 'max',max(len(x['output']) for x in rows))
