# Analyze outputs and all possible graders / reward clip variants

def nums(s): return re.findall(r'####\s*(-?[0-9][0-9,]*(?:\.[0-9]+)?)',s)
def ok(s,g):
 n=nums(s); return bool(n) and n[-1].replace(',','')==g.replace(',','')
