 for n in [100,200,300,400,500,800,1000,2000,100000]:
  a=sum(okclip(x['output'],x['gts'],n) for x in rows)/len(rows)
  print('clip',n,a)
 print('grader',sum(ok(x['output'],x['gts']) for x in rows)/len(rows),'logged',sum(x['score'] for x in rows)/len(rows))
 # mismatches grader vs logged
 ms=[x for x in rows if ok(x['output'],x['gts']) != bool(x['score'])]
 print('mismatch',len(ms))
 for x in ms[:3]: print('logged',x['score'],'nums',nums(x['output']), 'tail',repr(x['output'][-500:]))
